# Persamaan usulan final Fase 1B. Format: nama: (persamaan Vensim, satuan, kode K, sumber/kelas)
P = {}
def a(n, eq, u, k, s=""): P[n] = (eq, u, k, s)
# --- konfigurasi
a("Skenario Kebijakan", "1", "Dmnl", "S-1", "Desain: 1 = S1 PS pembiayaan terbatas; 2 = S2 PS + karbon")
a("Switch PS", "1", "Dmnl", "S-2", "Desain")
a("Switch Rehabilitasi", "1", "Dmnl", "S-3", "Desain")
a("Switch Pendanaan Awal", "1", "Dmnl", "S-4", "Desain")
a("Switch Karbon", "IF THEN ELSE(Skenario Kebijakan=2, STEP(1, Tahun Mulai Karbon), 0)", "Dmnl", "S-5", "Desain")
# --- K1 patroli reguler
a("Periode Pasca Pembiayaan Awal", "STEP(1, Tahun Akhir Pembiayaan Awal+1)", "Dmnl", "K1", "Struktur")
a("Anggota Patroli Roster 2025", "254", "People", "K1", "MR1 roster 2025 (B)")
a("HOK Patroli per Anggota 2025", "HOK Patroli Pembiayaan Awal Aktual 2025/Anggota Patroli Roster 2025", "HOK/(People*Year)", "K1", "Turunan data final 2025 (B)")
a("Tingkat Keberlanjutan Patroli Reguler", "0.5", "Dmnl", "K1", "D, nilai tengah eksploratif; sensitivitas 0-1")
a("Laju Penurunan Partisipasi Sukarela", "0", "1/Year", "K1", "D; sensitivitas 0-0,03")
a("Indeks Keberlanjutan Partisipasi", "EXP(-Laju Penurunan Partisipasi Sukarela*MAX(0, Time-(Tahun Akhir Pembiayaan Awal+1)))", "Dmnl", "K1", "Struktur")
a("Anggota Patroli Basis Reguler", "MIN(Anggota Patroli Aktif, Anggota Patroli Roster 2025)", "People", "K1", "Struktur")
a("HOK Patroli Reguler PS", "Switch PS*Periode Pasca Pembiayaan Awal*MIN(Kapasitas Hari Patroli Anggota, Anggota Patroli Basis Reguler*HOK Patroli per Anggota 2025*Tingkat Keberlanjutan Patroli Reguler*Indeks Keberlanjutan Partisipasi)", "HOK/Year", "K1", "Struktur")
a("Hari Patroli Swadaya", "HOK Patroli Reguler PS", "HOK/Year", "K1", "Alias kompatibilitas")
# --- K2
a("Proporsi Penggantian Anggota Patroli", "1", "Dmnl", "K2", "D (A1: 1); sensitivitas 0,625 (rasio kapasitas)")
a("Penambahan Anggota Patroli", "IF THEN ELSE(MAX(Periode Historis,Switch PS)=1, Pengurangan Anggota Patroli*Proporsi Penggantian Anggota Patroli+IF THEN ELSE(Alokasi Dana Perlindungan>0, 1, 0)*MIN(Kapasitas Penambahan Anggota Patroli BAU*Indeks Kapasitas LPHD, MAX(0, Anggota Patroli Dibutuhkan untuk Target-Anggota Patroli Aktif)/TIME STEP), 0)+Switch Pendanaan Awal*(Penambahan Anggota Patroli Tim Baru 2024*(STEP(1, 2024)-STEP(1, 2025))+Penambahan Anggota Patroli Tim Baru 2025*(STEP(1, 2025)-STEP(1, 2026)))", "People/Year", "K2", "")
# --- K3 patroli didanai & kebutuhan
a("Hari Patroli Didanai Kas LPHD", "(Pendanaan Awal untuk Patroli+Realisasi Belanja Perlindungan)/Biaya per Hari Patroli", "HOK/Year", "K3", "")
a("Hari Patroli Didanai", "Hari Patroli Pembiayaan Awal+Hari Patroli Didanai Kas LPHD", "HOK/Year", "K3", "")
a("Hari Patroli Didanai Kas Non Karbon", "Hari Patroli Didanai Kas LPHD*(1-Porsi Kas Karbon dalam Saldo)", "HOK/Year", "K3", "Pendekatan proporsional (B)")
a("Hari Patroli Tambahan Dibutuhkan", "Switch PS*MAX(0, MIN(Hari Patroli Target, Kapasitas Hari Patroli Anggota)-HOK Patroli Reguler PS-Hari Patroli Pembiayaan Awal)", "HOK/Year", "K3", "")
a("Indeks Intensitas Perlindungan", "IF THEN ELSE(Kebutuhan Hari Patroli>0, MIN(1, (HOK Patroli Reguler PS+Hari Patroli Didanai)/Kebutuhan Hari Patroli), 1)", "Dmnl", "K3", "")
a("Indeks Intensitas Perlindungan Tanpa Karbon", "IF THEN ELSE(Kebutuhan Hari Patroli>0, MIN(1, (HOK Patroli Reguler PS+Hari Patroli Pembiayaan Awal+Hari Patroli Didanai Kas Non Karbon)/Kebutuhan Hari Patroli), 1)", "Dmnl", "K3", "")
a("Kesenjangan Pembiayaan Minimum", "MAX(0, Kebutuhan Dana Minimum-Penggunaan Dana Pengelolaan)", "Rupiah/Year", "K3", "Hapus -Realisasi Pembiayaan Awal (sudah dikeluarkan dari kebutuhan dalam HOK)")
a("Kesenjangan Pembiayaan Semua Sumber", "MAX(0, Total Kebutuhan Dana Pengelolaan-Penggunaan Dana Pengelolaan)", "Rupiah/Year", "K3", "")
# --- K4 alokasi tanpa Switch Karbon
for cat, keb in [("Operasional LPHD", "Kebutuhan Dana Operasional LPHD"), ("Perlindungan", "Kebutuhan Dana Perlindungan"), ("Rehabilitasi", "Kebutuhan Dana Rehabilitasi"),
                 ("Penguatan Kelembagaan", "Kebutuhan Dana Penguatan Kelembagaan"), ("Pengembangan KUPS", "Kebutuhan Dana Pengembangan KUPS"), ("Pengendalian Kebakaran", "Kebutuhan Dana Pengendalian Kebakaran")]:
    a(f"Alokasi Dana {cat}", f"MIN(Dana Desa Tersedia*Proporsi Alokasi Efektif {cat}, {keb})", "Rupiah/Year", "K4", "")
# --- K5 kas LPHD
a("Switch Dana Non Karbon", "0", "Dmnl", "K5", "Desain; 1 bila ada data")
a("Dana Operasional Non Karbon Tunai", "0", "Rupiah/Year", "K5", "D, PERLU DATA")
a("Tahun Mulai Dana Non Karbon", "2026", "Year", "K5", "D")
a("Tahun Akhir Dana Non Karbon", "2087", "Year", "K5", "D")
a("Kas Masuk LPHD Non Karbon", "Switch PS*Switch Dana Non Karbon*Dana Operasional Non Karbon Tunai*(STEP(1, Tahun Mulai Dana Non Karbon)-STEP(1, Tahun Akhir Dana Non Karbon+1))", "Rupiah/Year", "K5", "")
a("Kas Masuk LPHD Karbon", "Dana Program PS dari Karbon", "Rupiah/Year", "K5", "")
a("Dana Desa Diterima", "Kas Masuk LPHD Karbon+Kas Masuk LPHD Non Karbon", "Rupiah/Year", "K5", "")
a("Saldo Dana LPHD dari Karbon", "INTEG(Kas Masuk LPHD Karbon-Penggunaan Dana Desa*Porsi Kas Karbon dalam Saldo, 0)", "Rupiah", "K5", "Stok pelacak sumber")
a("Porsi Kas Karbon dalam Saldo", "ZIDZ(Saldo Dana LPHD dari Karbon, Saldo Dana LPHD)", "Dmnl", "K5", "")
# --- K6 kelembagaan
a("Nilai Pendampingan Kelembagaan Non Tunai", "0", "Rupiah/Year", "K6", "D, PERLU DATA")
a("Laju Pembelajaran Kelembagaan", "0", "Dmnl", "K6", "D; sensitivitas 0-0,2")
a("Efek Pembelajaran Kelembagaan", "Laju Pembelajaran Kelembagaan*Indeks Intensitas Perlindungan", "Dmnl", "K6", "")
a("Faktor Penguatan Kelembagaan dari Karbon", "ZIDZ(Realisasi Belanja Penguatan Kelembagaan+Nilai Pendampingan Kelembagaan Non Tunai, Kebutuhan Dana Penguatan Kelembagaan)", "Dmnl", "K6", "Nama lama dipertahankan; isi = semua sumber")
a("Target Kapasitas LPHD", "Indeks Kapasitas LPHD Awal+(1-Indeks Kapasitas LPHD Awal)*MIN(1, Faktor Penguatan Kelembagaan dari Karbon+Efek Pembelajaran Kelembagaan)", "Dmnl", "K6", "")
# --- K7 KUPS
a("Porsi Laba Ditahan untuk Reinvestasi", "0.5", "Dmnl", "K7", "D; sensitivitas 0-1")
a("Biaya Reaktivasi KUPS", "Biaya Pembentukan KUPS", "Rupiah/Unit", "K7", "D; sensitivitas 0,25-1 x pembentukan")
a("Modal Usaha KUPS", "INTEG(Akumulasi Modal KUPS-Penggunaan Modal KUPS, 0)", "Rupiah", "K7", "")
a("Akumulasi Modal KUPS", "MAX(0, Laba KUPS Ditahan)*Porsi Laba Ditahan untuk Reinvestasi", "Rupiah/Year", "K7", "")
a("Penggantian KUPS Berbasis Modal", "MIN(KUPS Menjadi Tidak Aktif, Modal Usaha KUPS/TIME STEP/Biaya Reaktivasi KUPS)", "Unit/Year", "K7", "")
a("Penggunaan Modal KUPS", "Penggantian KUPS Berbasis Modal*Biaya Reaktivasi KUPS", "Rupiah/Year", "K7", "")
a("Penambahan KUPS", "IF THEN ELSE(Time < Tahun Akhir Data KUPS, Switch PS*Penambahan KUPS Historis, Switch PS*MIN(Penggantian KUPS Berbasis Modal+Pembentukan KUPS Dana Non Karbon+Pembentukan KUPS Didanai Karbon, MAX(Target Total KUPS-Jumlah KUPS Aktif,0)/TIME STEP+KUPS Menjadi Tidak Aktif))", "Unit/Year", "K7", "")
# --- K8
a("Pembentukan KUPS Didanai Karbon", "MIN(Target Pembentukan KUPS*Pengali Kapasitas Mode Lama, MAX(0, Realisasi Belanja Pengembangan KUPS-Jumlah KUPS Aktif*Biaya Pendampingan per KUPS per Tahun)/Biaya Pembentukan KUPS)", "Unit/Year", "K8", "nama dipertahankan; = didanai kas LPHD")
a("Pembentukan KUPS Direncanakan", "MAX(0, Alokasi Dana Pengembangan KUPS-Jumlah KUPS Aktif*Biaya Pendampingan per KUPS per Tahun)/Biaya Pembentukan KUPS", "Unit/Year", "K8", "")
a("Penanaman Didanai Karbon", "MIN(MIN(Dana Penanaman Rehabilitasi/Biaya Penanaman per Ha, Target Penanaman*Pengali Kapasitas Mode Lama), MAX(0, Luas Restorasi Selektif Eligible-Luas Tanam Didanai Karbon)/TIME STEP)", "Ha/Year", "K8", "")
a("Luas Penanaman Karbon Direncanakan", "MAX(0, Alokasi Dana Rehabilitasi-Kebutuhan Dana Pemeliharaan Rehabilitasi)/Biaya Penanaman per Ha", "Ha/Year", "K8", "")
# --- K9 rehabilitasi
a("Biaya Tenaga Penanaman per Ha", "HOK Penanaman per Ha*Upah Penanaman per HOK", "Rupiah/Ha", "K9", "Turunan (85 x 106.000)")
a("Biaya Bibit dan Material per Ha", "MAX(0, Biaya Penanaman per Ha-Biaya Tenaga Penanaman per Ha)", "Rupiah/Ha", "K9", "Turunan residual (B)")
a("Dukungan Material Rehabilitasi Non Karbon", "0", "Rupiah/Year", "K9", "D, PERLU DATA (program pemerintah/mitra)")
a("Penanaman Non Karbon", "Switch Rehabilitasi*(1-Periode Historis)*MIN(Proporsi Realisasi Penanaman BAU*Target Penanaman, ZIDZ(Dukungan Material Rehabilitasi Non Karbon, Biaya Bibit dan Material per Ha))", "Ha/Year", "K9", "")
a("Proporsi Realisasi Penanaman", "MIN(1, ZIDZ(Penanaman Non Karbon+Penanaman Didanai Karbon, Target Penanaman))", "Dmnl", "K9", "")
a("Penambahan Luas Penanaman", "Switch Rehabilitasi*(1-Periode Historis)*MIN(Proporsi Realisasi Penanaman*Target Penanaman, MIN(MAX(Target Total Penanaman RKPS-Luas Penanaman Program,0)/TIME STEP, NonHutan*Fraksi Maksimum NonHutan Ditanami per Tahun))", "Ha/Year", "K9", "persamaan A1 tetap")
a("Porsi Tenaga Penanaman Non Karbon Dibayar", "0", "Dmnl", "K9", "D; 0/1 sesuai program")
a("HOK Penanaman Didanai Kas", "Penanaman Didanai Karbon*HOK Penanaman per Ha", "HOK/Year", "K9", "")
a("HOK Penanaman Non Karbon", "MAX(0, HOK Penanaman-HOK Penanaman Didanai Kas)", "HOK/Year", "K9", "")
a("HOK Penanaman Berupah", "HOK Penanaman Didanai Kas+HOK Penanaman Non Karbon*Porsi Tenaga Penanaman Non Karbon Dibayar", "HOK/Year", "K9", "")
a("HOK Penanaman Sukarela", "HOK Penanaman Non Karbon*(1-Porsi Tenaga Penanaman Non Karbon Dibayar)", "HOK/Year", "K9", "")
a("Manfaat Ekonomi Penanaman", "HOK Penanaman Non Karbon*Porsi Tenaga Penanaman Non Karbon Dibayar*Upah Penanaman per HOK", "Rupiah/Year", "K9", "upah dibayar program non-karbon")
# --- K10 akuntansi biaya non karbon
a("Biaya Pengelolaan PS Non Karbon", "Anggota Patroli Berpartisipasi Reguler*Biaya Operasional Patroli Sukarela per Anggota per Tahun+Penanaman Non Karbon*Biaya Bibit dan Material per Ha+HOK Penanaman Non Karbon*Porsi Tenaga Penanaman Non Karbon Dibayar*Upah Penanaman per HOK+MAX(0, Jumlah KUPS Aktif-KUPS Didukung Karbon)*Biaya Pendampingan per KUPS per Tahun", "Rupiah/Year", "K10", "indikator, bukan kas")
a("Dana PS Eksisting", "Biaya Pengelolaan PS Non Karbon", "Rupiah/Year", "K10", "indikator")
# --- K11 non tunai
a("Upah Setara Non Tunai Patroli", "Upah Harian Patroli Berbayar", "Rupiah/HOK", "K11", "C")
a("Anggota Patroli Berpartisipasi Reguler", "ZIDZ(HOK Patroli Reguler PS, HOK Patroli per Anggota 2025)", "People", "K11", "")
a("HOK Sukarela PS", "HOK Patroli Reguler PS+HOK Penanaman Sukarela", "HOK/Year", "K11", "")
a("Nilai Kontribusi Tenaga Non Tunai", "HOK Patroli Reguler PS*Upah Setara Non Tunai Patroli+HOK Penanaman Sukarela*Upah Penanaman per HOK", "Rupiah/Year", "K11", "")
a("Nilai Logistik Non Tunai Patroli", "Anggota Patroli Berpartisipasi Reguler*Biaya Operasional Patroli Sukarela per Anggota per Tahun", "Rupiah/Year", "K11", "File A (C)")
a("Nilai Kontribusi Swadaya", "Nilai Kontribusi Tenaga Non Tunai+Nilai Logistik Non Tunai Patroli", "Rupiah/Year", "K11", "nama lama")
a("HOK Patroli", "0", "HOK/Year", "K11", "patroli sukarela dipindah ke HOK Sukarela PS")
# --- K12 kerja
a("HOK Berupah PS", "Hari Patroli Didanai+HOK Penanaman Berupah+HOK Pengendalian Kebakaran", "HOK/Year", "K12", "")
a("Kesempatan Kerja PS", "HOK Berupah PS+HOK Sukarela PS", "HOK/Year", "K12", "")
