a("Kesempatan Kerja Sukarela Setara Penuh", "HOK Sukarela PS/HOK Tersedia per Anggota Kerja per Tahun", "People", "K12", "")
a("Upah Kegiatan PS", "Upah Patroli Berbayar+Manfaat Ekonomi Penanaman+Upah Penanaman Didanai Karbon+Upah Pengendalian Kebakaran", "Rupiah/Year", "K12", "A1 memuat Manfaat Ekonomi Patroli (=0); upah tanam didanai kas ditambahkan")
# --- K13
a("Anggota Patroli Berpartisipasi", "MIN(Anggota Patroli Aktif, ZIDZ(HOK Patroli Reguler PS+Hari Patroli Didanai, HOK Patroli per Anggota 2025))", "People", "K13", "")
a("Total Partisipasi Kegiatan PS", "Anggota KUPS Aktif+Anggota Patroli Berpartisipasi+Penerima Manfaat Penanaman Aktif", "People", "K13", "")
# --- K14
a("Keikutsertaan Patroli 2023", "2160", "HOK/Year", "K14", "392 kegiatan x 5,51 (estimasi peneliti, B)")
a("Indeks Intensitas Patroli 2023", "Keikutsertaan Patroli 2023/INITIAL(Kebutuhan Hari Patroli)", "Dmnl", "K14", "")
