a("Efek Pengelolaan PS Tanpa Karbon", "Switch PS*Switch Dampak Skenario Lahan*SMOOTHI(Respons Perlindungan Tanpa Karbon, Waktu Penyesuaian Efek Pengelolaan PS, Respons Perlindungan Awal)*Efektivitas Perlindungan Penuh terhadap Deforestasi", "Dmnl", "K14", "")
# --- K15
a("Tingkat Kecukupan Patroli Referensi", "INITIAL(Tingkat Kecukupan Anggota Patroli)", "Dmnl", "K15", "")
