a("Kas Penjualan Kredit", "IF THEN ELSE(Delay Pembayaran Penjualan>0, DELAY FIXED(Pendapatan Kotor Penjualan Kredit, Delay Pembayaran Penjualan, 0), Pendapatan Kotor Penjualan Kredit)", "Rupiah/Year", "C1", "")
